import json

# Load all node definitions
with open('/tmp/receipts_registry.json') as f:
    receipts_d = json.load(f)
with open('/tmp/end_node.json') as f:
    end_d = json.load(f)
with open('/tmp/script_node.json') as f:
    script_d = json.load(f)

receipts_node = receipts_d['Data']['Node']
end_node = end_d['Data']['Node']
script_node = script_d['Data']['Node']

model_blob = receipts_node['inputDefaults']['model']
# modelName is null — use modelDisplayName
if not model_blob.get('modelName'):
    model_blob = dict(model_blob)
    model_blob['modelName'] = model_blob['modelDisplayName']

out_output = receipts_node['outputDefinition']['output']
out_error = receipts_node['outputDefinition']['error']

